short=open("/tmp/caps/help_short.txt").read()
long_ext=open("/tmp/caps/help_long.txt").read()
# long = banner + blank + short + rest
assert short in long_ext
rest=long_ext[long_ext.index(short)+len(short):]
def esc(s):
    out=[]
    for ch in s:
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\n': out.append('\\n')
        else: out.append(ch)
    return ''.join(out)
with open("help_text.h","w") as f:
    f.write("static const char kShortHelpTemplate[] =\n")
    # split lines keeping \n
    for line in short.splitlines(True):
        line2=line.replace("executable","%s",1) if "Usage:" in line else line
        f.write(f'    "{esc(line2)}"\n')
    f.write(";\nstatic const char kLongHelpExtra[] =\n")
    for line in rest.splitlines(True):
        f.write(f'    "{esc(line)}"\n')
    f.write(";\n")
print(open("help_text.h").read()[:1000])
PY
python3 /tmp/gen_help.py"}

