/* human readable */
static void make_human(unsigned long long size, char* buf, size_t bufsz){
    /* returns string like "    24 B" or " 1.000 KiB" : numeric field width 6 then space then unit */
    const char* units[]={"B","KiB","MiB","GiB","TiB","PiB","EiB"};
    if(size<1024){
        snprintf(buf,bufsz,"%6llu %s",(unsigned long long)size,units[0]);
        return;
    }
    int u=0; double v=(double)size;
    while(v>=1024.0 && u<6){ v/=1024.0; u++; }
    /* Actually compute exact unit by integer division steps */
    {
        unsigned long long s=size; u=0; while(s>=1024 && u<6){ s/=1024; u++; }
        v=(double)size; for(int i=0;i<u;i++) v/=1024.0;
    }
    char num[32];
    if(v==1.0) snprintf(num,sizeof(num),"%.3f",v);
    else if(v<10.0) snprintf(num,sizeof(num),"%.2f",v);
    else if(v<100.0) snprintf(num,sizeof(num),"%.1f",v);
    else snprintf(num,sizeof(num),"%.0f",v);
    snprintf(buf,bufsz,"%6s %s",num,units[u]);
}
static void make_human_fixed_unit(unsigned long long size, char* numbuf, size_t nsz, char* unitbuf){
    /* for -l columns: numeric string and unit separately */
    const char* units[]={"B","KiB","MiB","GiB","TiB","PiB","EiB"};
    if(size<1024){ snprintf(numbuf,nsz,"%llu",(unsigned long long)size); strcpy(unitbuf,units[0]); return; }
    unsigned long long s=size; int u=0; while(s>=1024 && u<6){ s/=1024; u++; }
    double v=(double)size; for(int i=0;i<u;i++) v/=1024.0;
    if(v==1.0) snprintf(numbuf,nsz,"%.3f",v);
    else if(v<10.0) snprintf(numbuf,nsz,"%.2f",v);
    else if(v<100.0) snprintf(numbuf,nsz,"%.1f",v);
    else snprintf(numbuf,nsz,"%.0f",v);
    strcpy(unitbuf,units[u]);
}

/* number parsing */
static int parse_size_strict(const char* s, unsigned long long* out){
    /* returns 1 ok, 0 error */
    unsigned long long val=0; int ndig=0;
    const char* p=s;
    while(isdigit((unsigned char)*p)){ val=val*10+(*p-'0'); p++; ndig++; }
    unsigned long long mult=1;
    if(!strcmp(p,"")) mult=1;
    else if(!strcmp(p,"K")||!strcmp(p,"KB")||!strcmp(p,"KiB")) mult=1024ULL;
    else if(!strcmp(p,"M")||!strcmp(p,"MB")||!strcmp(p,"MiB")) mult=1024ULL*1024ULL;
    else return 0;
    (void)ndig;
    *out=val*mult;
    return 1;
}
static unsigned long long read_size_lenient(const char** pp){
    const char* p=*pp; unsigned long long val=0;
    while(isdigit((unsigned char)*p)){ val=val*10+(*p-'0'); p++; }
    if(*p=='K'){ val*=1024ULL; p++; if(*p=='B') p++; else if(*p=='i'){ p++; if(*p=='B') p++; } }
    else if(*p=='M'){ val*=1024ULL*1024ULL; p++; if(*p=='B') p++; else if(*p=='i'){ p++; if(*p=='B') p++; } }
    else if(*p=='G'){ val*=1024ULL*1024ULL*1024ULL; p++; if(*p=='B') p++; else if(*p=='i'){ p++; if(*p=='B') p++; } }
    *pp=p; return val;
}
static unsigned read_u32_lenient(const char** pp){
    const char* p=*pp; unsigned long long v=0;
    while(isdigit((unsigned char)*p)){ v=v*10+(*p-'0'); p++; }
    *pp=p; return (unsigned)v;
}

