/* ---------- output writer ---------- */
typedef struct {
    FILE* fp; int fd; int is_stdout; int is_file; int sparse;
    unsigned long long written; /* logical size including skipped zeros */
    unsigned long long pendingZeros;
    int error;
} OutWriter;
static int ow_flush_zeros(OutWriter* w, int final_write){
    if(w->pendingZeros==0) return 0;
    if(final_write){
        /* write last zero byte to set size/allocation, seek over rest */
        if(w->pendingZeros>1){ if(lseek(w->fd,(off_t)(w->pendingZeros-1),SEEK_CUR)<0) return -1; }
        unsigned char z=0; if(write(w->fd,&z,1)!=1) return -1;
        w->pendingZeros=0; return 0;
    } else {
        if(lseek(w->fd,(off_t)w->pendingZeros,SEEK_CUR)<0) return -1;
        w->pendingZeros=0; return 0;
    }
}
static int ow_write(OutWriter* w, const void* data, size_t len){
    if(len==0) return 0;
    w->written+=len;
    if(w->error) return -1;
    if(w->sparse && w->is_file){
        const unsigned char* p=(const unsigned char*)data; size_t i=0;
        while(i<len){
            if(p[i]==0){ w->pendingZeros++; i++; continue; }
            if(w->pendingZeros){ if(ow_flush_zeros(w,0)!=0){ w->error=errno; return -1; } }
            /* write run of non-zero up to next zero (scan) */
            size_t j=i; while(j<len && p[j]!=0) j++;
            /* For sparse efficiency, this byte scan is okay; write chunk */
            size_t remain=j-i; const unsigned char* q=p+i;
            while(remain){ ssize_t r=write(w->fd,q,remain); if(r<=0){ w->error=errno?errno:EIO; return -1; } q+=r; remain-=r; }
            i=j;
        }
        return 0;
    } else {
        size_t r=fwrite(data,1,len,w->fp);
        if(r!=len){ w->error=errno?errno:EIO; return -1; }
        return 0;
    }
}
static int ow_close(OutWriter* w){
    int ret=0;
    if(w->sparse && w->is_file){
        if(w->pendingZeros){ if(ow_flush_zeros(w,1)!=0) ret=-1; }
        if(close(w->fd)!=0) ret=-1;
    } else {
        if(w->fp && !w->is_stdout){ if(fclose(w->fp)!=0) ret=-1; }
        else if(w->fp){ if(fflush(w->fp)!=0) ret=-1; }
    }
    if(w->error) ret=-1;
    return ret;
}

/* ---------- frame parsing for list / info ---------- */
typedef struct {
    unsigned long long compressedSize; /* total file bytes consumed by valid frames or file size on error trunc */
    unsigned long long decompressedSize; int hasDecompressedSize;
    unsigned long long windowSize;
    unsigned dictID;
    int nbFrames; int nbSkips;
    int hasChecksum; int singleFrameHasChecksum; unsigned checksumValue; int hasChecksumValue;
    int parseError; /* 0 ok, 1 not zstd, 2 trunc etc */
    int errKind; /* 0 none,1 reachEOF(incomplete frame <6),2 block header,3 checksum,4 not zstd */
} FileInfo;

static unsigned rd32le(const unsigned char* p){ return p[0]|(p[1]<<8)|(p[2]<<16)|((unsigned)p[3]<<24); }
static unsigned long long rd64le(const unsigned char* p){ unsigned long long v=0; for(int i=0;i<8;i++) v|=((unsigned long long)p[i])<<(8*i); return v; }

static int is_skippable_magic(const unsigned char* p){ return p[0]>=0x50&&p[0]<=0x5F&&p[1]==0x2A&&p[2]==0x4D&&p[3]==0x18; }
static int is_zstd_magic(const unsigned char* p){ return p[0]==0x28&&p[1]==0xB5&&p[2]==0x2F&&p[3]==0xFD; }
static int is_legacy_magic(const unsigned char* p){ return p[1]==0xB5&&p[2]==0x2F&&p[3]==0xFD&&p[0]>=0x1E&&p[0]<=0x27; }

/* parse one standard frame from buffer at offset, fill info; return consumed or 0 on error */
static int parse_headers_only(const unsigned char* buf, size_t len, FileInfo* info){
    /* iterate frames using header parsing + block scanning */
    size_t pos=0;
    info->compressedSize=0; info->decompressedSize=0; info->hasDecompressedSize=1;
    info->windowSize=0; info->dictID=0; info->nbFrames=0; info->nbSkips=0;
    info->hasChecksum=0; info->parseError=0; info->errKind=0; info->hasChecksumValue=0;
    while(pos<len){
        size_t remaining=len-pos;
        if(remaining<6){
            if(info->nbFrames==0&&info->nbSkips==0){ info->parseError=1; info->errKind=1; return 0; }
            else { /* ignore trailing <6 as in original for list */ break; }
        }
        const unsigned char* p=buf+pos;
        if(is_skippable_magic(p)){
            if(remaining<8){ info->parseError=1; info->errKind=1; return 0; }
            unsigned sz=rd32le(p+4);
            if(remaining<8+(size_t)sz){ info->parseError=1; info->errKind=3; info->compressedSize=len; return 0; }
            pos+=8+sz; info->nbSkips++; continue;
        }
        if(!is_zstd_magic(p)&&!is_legacy_magic(p)){ info->parseError=1; info->errKind=4; return 0; }
        if(is_legacy_magic(p)){
            /* use library to find frame size */
            if(!load_zstd()){ info->parseError=1; return 0; }
            size_t fsize=p_ZSTD_findFrameCompressedSize(p,remaining);
            if(p_ZSTD_isError(fsize)){ info->parseError=1; info->errKind=2; info->compressedSize=len; return 0; }
            info->nbFrames++; pos+=fsize;
            info->hasDecompressedSize=0;
            continue;
        }
        /* standard */
        unsigned char fhd=p[4];
        unsigned fcsFlag=fhd>>6;
        int singleSeg=(fhd>>5)&1;
        int checksumFlag=(fhd>>2)&1;
        unsigned dictFlag=fhd&3;
        size_t off=5;
        unsigned long long windowSize=0;
        unsigned char wd=0;
        if(!singleSeg){ if(off>=remaining){ info->parseError=1; info->errKind=2; info->compressedSize=len; return 0; } wd=p[off++]; }
        unsigned dictID=0;
        size_t dictSize = dictFlag==0?0: dictFlag==1?1: dictFlag==2?2:4;
        if(off+dictSize>remaining){ info->parseError=1; info->errKind=2; info->compressedSize=len; return 0; }
        for(size_t i=0;i<dictSize;i++) dictID |= ((unsigned)p[off+i])<<(8*i);
        off+=dictSize;
        size_t fcsSize=0;
        if(singleSeg){ fcsSize = fcsFlag==0?1: fcsFlag==1?2: fcsFlag==2?4:8; }
        else { fcsSize = fcsFlag==0?0: fcsFlag==1?2: fcsFlag==2?4:8; }
        unsigned long long contentSize=0; int hasContent=1;
        if(fcsSize==0) hasContent=0;
        else {
            if(off+fcsSize>remaining){ info->parseError=1; info->errKind=2; info->compressedSize=len; return 0; }
            unsigned long long v=0;
            if(fcsSize==1) v=p[off];
            else if(fcsSize==2) v=(p[off]|(p[off+1]<<8))+256;
            else if(fcsSize==4) v=rd32le(p+off);
            else v=rd64le(p+off);
            contentSize=v; off+=fcsSize;
        }
        if(singleSeg) windowSize=contentSize;
        else {
            unsigned exp=wd>>3; unsigned mant=wd&7;
            unsigned long long base=1ULL<<(10+exp);
            windowSize=base + (base/8)*mant;
        }
        info->windowSize=windowSize;
        info->dictID=dictID;
        if(hasContent){ info->decompressedSize+=contentSize; }
        else info->hasDecompressedSize=0;
        /* scan blocks */
        size_t bpos=off;
        int frameDone=0;
        int localChecksumSeen=0;
        while(!frameDone){
            if(bpos+3>remaining){
                /* original prints row even on truncated, frames not counted */
                info->parseError=1; info->errKind=2; info->compressedSize=len;
                if(bpos+3<=remaining) localChecksumSeen=checksumFlag;
                /* For trunc at header stage, check field may be None unless block header fully read; handled by caller using errKind */
                return 0;
