    OutWriter sharedWriter; memset(&sharedWriter,0,sizeof(sharedWriter));
    struct stat sharedSrcStat; int haveSharedSrcStat=0;
    if(g_op!=OP_TEST){
        if(g_toStdout){ sharedMode=1; sharedIsStdout=1; }
        else if(g_outFile){ sharedMode=1; sharedDst=g_outFile; }
