            if(g_display>=4){ fprintf(stderr,"Using stdout for output \n"); if(g_op==OP_DECOMPRESS && g_sparse==-1) fprintf(stderr,"Sparse File Support is automatically disabled on stdout ; try --sparse \n"); }
        } else {
            /* derive */
            char* derived=derive_output_name(src, g_op==OP_DECOMPRESS);
            if(!derived){
                if(g_display>=1) fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz/.lzma/.xz/.txz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n", src);
                g_result=1; if(!isStdin) fclose(inFp); continue;
            }
