/* ---------- benchmark ---------- */
static unsigned char* gen_lorem(size_t n){
    static const char* words[]={"Lorem","ipsum","dolor","sit","amet","consectetur","adipiscing","elit","sed","do","eiusmod","tempor","incididunt","ut","labore","et","dolore","magna","aliqua","enim","ad","minim","veniam","quis","nostrud","exercitation","ullamco","laboris","nisi","aliquip","ex","ea","commodo","consequat","Duis","aute","irure","in","reprehenderit","voluptate","velit","esse","cillum","fugiat","nulla","pariatur","Excepteur","sint","occaecat","cupidatat","non","proident","sunt","culpa","qui","officia","deserunt","mollit","anim","id","est","laborum",NULL};
    int nw=0; while(words[nw]) nw++;
    unsigned char* buf=xmalloc(n+1); size_t pos=0; unsigned long long rng=12345;
    while(pos<n){
        rng=rng*6364136223846793005ULL+1442695040888963407ULL;
        const char* w=words[(rng>>33)%nw];
        size_t wl=strlen(w);
        if(pos+wl+1>=n) break;
        memcpy(buf+pos,w,wl); pos+=wl; buf[pos++]=' ';
        if(((rng>>20)%12)==0) buf[pos-1]='.';
    }
    buf[pos]=0; return buf;
}
static size_t bench_one_shot_compress(const unsigned char* src, size_t len, unsigned char* dst, size_t cap, int level){
    void* ctx=p_ZSTD_createCCtx(); if(!ctx) return 0;
    if(g_dictLoaded&&g_dictSize&&p_ZSTD_CCtx_loadDictionary) p_ZSTD_CCtx_loadDictionary(ctx,g_dictBuf,g_dictSize);
    p_ZSTD_CCtx_setParameter(ctx,100,level); p_ZSTD_CCtx_setParameter(ctx,201,g_checksum?1:0);
    size_t (*c2)(void*,void*,size_t,const void*,size_t)=(void*)dlsym(g_zhandle,"ZSTD_compress2");
    size_t r;
    if(c2) r=c2(ctx,dst,cap,src,len);
    else r=0;
    p_ZSTD_freeCCtx(ctx);
    if(p_ZSTD_isError(r)) return 0; return r;
}
static size_t bench_one_shot_decompress(const unsigned char* src, size_t len, unsigned char* dst, size_t cap){
    size_t (*dec)(void*,size_t,const void*,size_t)=(void*)dlsym(g_zhandle,"ZSTD_decompress");
    if(!dec) return 0;
    /* dictionary decompress one-shot not supported simply; ignore dict for bench decompress if dict present use DCtx */
    if(g_dictLoaded&&g_dictSize){
        void* ctx=p_ZSTD_createDCtx(); if(p_ZSTD_DCtx_loadDictionary) p_ZSTD_DCtx_loadDictionary(ctx,g_dictBuf,g_dictSize);
        size_t (*dd)(void*,void*,size_t,const void*,size_t)=(void*)dlsym(g_zhandle,"ZSTD_decompressDCtx");
        size_t r=dd?dd(ctx,dst,cap,src,len):0; p_ZSTD_freeDCtx(ctx); if(p_ZSTD_isError(r)) return 0; return r;
    }
    size_t r=dec(dst,cap,src,len); if(p_ZSTD_isError(r)) return 0; return r;
}
static int execute_bench(void){
    if(g_display>=3) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n");
    int startLevel=g_benchLevelSet? g_level:3;
    /* -b sets g_level as start in our parser; -e sets high */
    int endLevel=g_benchHighLevel; if(endLevel<startLevel) endLevel=startLevel;
    int rc=load_dictionary_if_needed(); if(rc) return rc;
    if(!load_zstd()) return 1;
    if(g_display>=3) fprintf(stderr,"Benchmarking at level %d using %d threads \n", startLevel, resolve_threads_for_display());
    /* prepare datasets */
    typedef struct { char* name; unsigned char* data; size_t len; } BenchSet;
    BenchSet* sets=NULL; size_t nSets=0;
    if(g_nExpanded==0){
        sets=xmalloc(sizeof(BenchSet)); sets[0].name=xstrdup("Lorem ipsum"); sets[0].data=gen_lorem(10000000); sets[0].len=10000000; nSets=1;
    } else if(g_separateFiles){
        sets=xmalloc(sizeof(BenchSet)*g_nExpanded); nSets=0;
        for(size_t i=0;i<g_nExpanded;i++){
            if(!strcmp(g_expanded[i],"-")) continue;
            printf("Loading %s...       \r", g_expanded[i]); fflush(stdout);
            size_t len=0; unsigned char* d=read_file_path(g_expanded[i],&len);
            printf("\r                                                                               \r"); fflush(stdout);
            if(!d){ if(g_display>=1) fprintf(stderr,"Error loading files\n"); return 15; }
            sets[nSets].name=xstrdup(g_expanded[i]); sets[nSets].data=d; sets[nSets].len=len; nSets++;
        }
    } else {
        /* consolidate */
        size_t total=0; for(size_t i=0;i<g_nExpanded;i++){ struct stat st; if(!strcmp(g_expanded[i],"-")) continue; if(stat(g_expanded[i],&st)==0) {} }
        unsigned char* all=NULL; size_t allLen=0,allCap=0;
        for(size_t i=0;i<g_nExpanded;i++){
            if(!strcmp(g_expanded[i],"-")) continue;
            printf("Loading %s...       \r", g_expanded[i]); fflush(stdout);
            size_t len=0; unsigned char* d=read_file_path(g_expanded[i],&len);
            printf("\r                                                                               \r"); fflush(stdout);
            if(!d){ fprintf(stderr,"Error loading files\n"); return 15; }
            if(allLen+len>allCap){ allCap=(allLen+len)*2+1024; all=realloc(all,allCap); }
            memcpy(all+allLen,d,len); allLen+=len; free(d);
        }
        sets=xmalloc(sizeof(BenchSet)); char nm[64]; if(g_nExpanded==1) snprintf(nm,sizeof(nm),"%s",g_expanded[0]); else snprintf(nm,sizeof(nm),"%d files",(int)g_nExpanded);
        sets[0].name=xstrdup(nm); sets[0].data=all; sets[0].len=allLen; nSets=1; (void)total;
    }
    static const char spinner[]={'|','/','=','\\'};
    for(size_t si=0; si<nSets; si++){
        BenchSet* bs=&sets[si];
        for(int lvl=startLevel; lvl<=endLevel; lvl++){
            /* compressed buffer */
            size_t cap;
            {
                /* compress chunks if split */
                size_t worst=0; size_t chunk = g_splitSize? (size_t)g_splitSize : bs->len;
                if(chunk==0) chunk=bs->len?bs->len:1;
                for(size_t off=0; off<bs->len; off+=chunk){ size_t clen=bs->len-off<chunk?bs->len-off:chunk; worst+=p_ZSTD_compressBound(clen)+64; }
                if(bs->len==0) worst=p_ZSTD_compressBound(0)+64;
                cap=worst;
            }
            unsigned char* comp=xmalloc(cap); unsigned char* decomp=xmalloc(bs->len?bs->len:1);
            /* function to compress whole set (with split) and return comp size */
            /* we compress once to fill comp for decompression bench; chunks concatenated with individual frames, decompression bench decodes each frame sequentially */
            size_t compSize=0;
            {
                size_t chunk = g_splitSize? (size_t)g_splitSize : bs->len; if(chunk==0) chunk=1;
                if(bs->len==0){ compSize=bench_one_shot_compress(bs->data,0,comp,cap,lvl); }
                for(size_t off=0; off<bs->len; off+=chunk){ size_t clen=bs->len-off<chunk?bs->len-off:chunk; size_t r=bench_one_shot_compress(bs->data+off,clen,comp+compSize,cap-compSize,lvl); compSize+=r; }
            }
            double bestCompSpeed=0,bestDecompSpeed=0; int round=0; double cum=0;
            while(1){
                char spin=spinner[round%4];
                printf("\r %c-%-18s: %8llu -> ", spin, bs->name, (unsigned long long)bs->len); fflush(stdout);
                /* compress eval */
                {
                    int iters=1; double elapsed=0;
                    while(1){
                        long long t0=now_ns(); size_t cs=0;
